 const [zoom,setZoom]=useState(100);const [showGrid,setShowGrid]=useState(false);const [search,setSearch]=useState('');
 const [exportOpen,setExportOpen]=useState(false);const [activeTab,setActiveTab]=useState<'properties'|'layers'|'style'>('properties');const [panelOpen,setPanelOpen]=useState(true);
 const [status,setStatus]=useState('World ready');const [draggingReference,setDraggingReference]=useState(false);const [seedInput,setSeedInput]=useState('');const [aiOpen,setAiOpen]=useState(false);const [aiEndpoint,setAiEndpoint]=useState(()=>localStorage.getItem('worldbuild-ai-endpoint')||'http://localhost:11434/v1/chat/completions');const [aiModel,setAiModel]=useState(()=>localStorage.getItem('worldbuild-ai-model')||'qwen2.5:7b');const [aiKey,setAiKey]=useState('');const [aiPrompt,setAiPrompt]=useState('');const [aiLoading,setAiLoading]=useState(false);const [aiReply,setAiReply]=useState('');const [aiPending,setAiPending]=useState<{message:string;operations:Record<string,unknown> []}|null>(null);
 const svgRef=useRef<SVGSVGElement>(null);const imageInputRef=useRef<HTMLInputElement>(null);const projectInputRef=useRef<HTMLInputElement>(null);const dragStart=useRef<{x:number;y:number;refX:number;refY:number}|null>(null);
 const features=project.features;const referenceImage=project.referenceImage||null;const appearance={...DEFAULT_APPEARANCE,...project.appearance};const updateAppearance=(patch:Partial<Appearance>)=>setProject(p=>({...p,appearance:{...DEFAULT_APPEARANCE,...p.appearance,...patch}}));
