 const addFeature=(kind:Kind,x=450,y=350)=>{const defaults:Record<Kind,string>={region:'New region',water:'New water body',mountain:'Unnamed peak',city:'New city',village:'New village',river:'Unnamed river',forest:'Forest',road:'Road',label:'New label'};const f:Feature={id:uid(),kind,name:defaults[kind],x,y,points:['river','road'].includes(kind)?`M ${x-55} ${y-75} Q ${x-15} ${y-25} ${x} ${y} T ${x+55} ${y+75}`:['region','water','forest'].includes(kind)?`M ${x-35} ${y-20} Q ${x} ${y-45} ${x+35} ${y-10} Q ${x+45} ${y+25} ${x+5} ${y+30} Q ${x-35} ${y+30} ${x-35} ${y-20} Z`:undefined};commit({...project,features:[...features,f]},'Feature added');setSelected(f.id);setTool('select');setActiveTab('properties');};
