 const askWorldbuildAI=async()=>{if(!aiEndpoint.trim()||!aiModel.trim()||!aiPrompt.trim())return;setAiLoading(true);setAiPending(null);setAiReply('');localStorage.setItem('worldbuild-ai-endpoint',aiEndpoint);localStorage.setItem('worldbuild-ai-model',aiModel);const system=`You are the WorldbuildApp worldbuilding editor. Respond ONLY as valid JSON: {"message":"brief useful explanation","operations":[...]}. Available operations: {"type":"rename","id":"existing feature id","name":"new name"}; {"type":"notes","id":"existing feature id","notes":"lore text"}; {"type":"title","title":"world title"}; {"type":"add","kind":"city|village|region|water|river|forest|mountain|road|label","name":"name","x":number,"y":number,"notes":"optional lore"}; {"type":"appearance","paper":"#hex","land":"#hex","water":"#hex","forest":"#hex","river":"#hex","accent":"#hex"}. Coordinates must be within x 20..880 and y 20..680. Only use existing IDs from the supplied map. Never output code, SVG, HTML, or unsupported operations. Prefer distinctive, culturally varied names; avoid generic fantasy names like Aerola or Arthelgard. Keep changes coherent with the request.`;const context={title:project.title,features:features.map(f=>({id:f.id,kind:f.kind,name:f.name,x:f.x,y:f.y,notes:f.notes})).slice(0,180),appearance};try{const response=await fetch(aiEndpoint,{method:'POST',headers:{'Content-Type':'application/json',...(aiKey.trim()?{Authorization:'Bearer '+aiKey.trim()}:{})},body:JSON.stringify({model:aiModel,messages:[{role:'system',content:system},{role:'user',content:'Current map JSON context: '+JSON.stringify(context)+'\nUser request: '+aiPrompt}],temperature:.7})});if(!response.ok)throw new Error('Provider returned HTTP '+response.status+' '+response.statusText);const data=await response.json();let raw=String(data.choices?.[0]?.message?.content||'');raw=raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const parsed=JSON.parse(raw);if(!Array.isArray(parsed.operations))throw new Error('The model response did not contain an operations array.');const allowedKinds:Kind[]=['region','water','mountain','city','village','river','forest','road','label'];const valid=parsed.operations.filter((o:Record<string,unknown>)=>{if(!o||typeof o.type!=='string')return false;if(o.type==='rename'||o.type==='notes')return typeof o.id==='string'&&features.some(f=>f.id===o.id);if(o.type==='title')return typeof o.title==='string';if(o.type==='add')return allowedKinds.includes(o.kind as Kind)&&typeof o.name==='string'&&Number.isFinite(o.x)&&Number.isFinite(o.y);if(o.type==='appearance')return ['paper','land','water','forest','river','accent'].some(k=>typeof o[k]==='string'&&/^#[0-9a-f]{6}$/i.test(String(o[k])));return false;}).slice(0,40);setAiPending({message:String(parsed.message||'Review the proposed map edits.'),operations:valid});setAiReply(valid.length?'Review the proposed operations below before applying them.':'The model returned no valid map operations. Try a more specific request.');}catch(e){setAiReply('AI request failed: '+(e instanceof Error?e.message:String(e))+' — check the endpoint, model name, provider key and browser CORS settings.');}finally{setAiLoading(false);}};
 const applyAiChanges=()=>{if(!aiPending)return;let next:WorldProject={...project,features:project.features.map(f=>({...f})),appearance:{...DEFAULT_APPEARANCE,...project.appearance}};for(const o of aiPending.operations){if(o.type==='rename')next.features=next.features.map(f=>f.id===o.id?{...f,name:String(o.name).slice(0,100)}:f);else if(o.type==='notes')next.features=next.features.map(f=>f.id===o.id?{...f,notes:String(o.notes).slice(0,2000)}:f);else if(o.type==='title')next.title=String(o.title).slice(0,100);else if(o.type==='add'){const kind=o.kind as Kind,x=Math.max(20,Math.min(880,Number(o.x))),y=Math.max(20,Math.min(680,Number(o.y)));next.features.push({id:uid(),kind,name:String(o.name).slice(0,100),x,y,notes:typeof o.notes==='string'?o.notes.slice(0,2000):undefined,points:['region','water','forest'].includes(kind)?`M ${x-25} ${y-15} Q ${x} ${y-35} ${x+27} ${y-10} Q ${x+35} ${y+15} ${x+3} ${y+25} Q ${x-30} ${y+20} ${x-25} ${y-15} Z`:undefined});}else if(o.type==='appearance'){const patch:Partial<Appearance>={};for(const k of ['paper','land','water','forest','river','accent'] as const)if(typeof o[k]==='string'&&/^#[0-9a-f]{6}$/i.test(String(o[k])))patch[k]=String(o[k]);next.appearance={...DEFAULT_APPEARANCE,...next.appearance,...patch};}}commit(next,'AI edits applied · '+aiPending.operations.length+' operations');setAiPending(null);setAiPrompt('');setAiReply('Changes applied. Use Undo to revert the entire AI edit batch.');};
