 const importImage=(file?:File)=>{if(!file)return;if(!file.type.startsWith('image/')){setStatus('Choose an image file');return;}if(file.size>6*1024*1024){setStatus('Image is over 6 MB; resize it and try again');return;}const reader=new FileReader();reader.onload=()=>{const source=String(reader.result||'');const image=new Image();image.onload=()=>{const maxW=1600,maxH=1200,scale=Math.min(1,maxW/(image.naturalWidth||maxW),maxH/(image.naturalHeight||maxH));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((image.naturalWidth||maxW)*scale));canvas.height=Math.max(1,Math.round((image.naturalHeight||maxH)*scale));const ctx=canvas.getContext('2d');if(!ctx){setStatus('Image processing is unavailable in this browser');return;}ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL('image/jpeg',.78);const width=Math.min(760,canvas.width),height=width*(canvas.height/canvas.width),fit=Math.min(1,620/height),w=width*fit,h=height*fit;setReference({dataUrl,name:file.name,x:(MAP_W-w)/2,y:(MAP_H-h)/2,width:w,height:h,opacity:.48,visible:true,locked:false});setLayers(l=>({...l,reference:true}));setActiveTab('layers');setStatus('Reference image imported and optimized');};image.onerror=()=>setStatus('Could not read that image');image.src=source;};reader.onerror=()=>setStatus('Could not read that image');reader.readAsDataURL(file);};
