 if(f.kind==='region'||f.kind==='water'||f.kind==='forest')return <g {...common} transform={(f.kind==='water'||f.kind==='region'||f.kind==='forest')?`translate(${f.x} ${f.y}) scale(${(f.size||1)*(f.kind==='water'?(f.rx||1):1)} ${(f.size||1)*(f.kind==='water'?(f.ry||1):1)}) translate(${-f.x} ${-f.y})`:undefined}><path d={f.points||`M ${f.x-30} ${f.y-20} q 30 -25 60 0 q 15 30 -15 45 q -35 10 -45 -25 z`} fill={f.color||(f.kind==='water'?appearance.water:f.kind==='forest'?appearance.forest:selected===f.id?appearance.accent:appearance.land)} fillOpacity={f.kind==='region'&&referenceImage&&referenceImage.visible&&layers.reference?0.62:1} stroke={selected===f.id?appearance.accent:f.kind==='water'?appearance.river:appearance.border} strokeWidth={selected===f.id?2.6:1.4} strokeLinejoin="round"/><text x={f.x} y={f.y} textAnchor="middle" className="region-label" style={{fill:appearance.text,display:appearance.showFeatureLabels?"":"none",fontSize:appearance.labelSize,fontFamily:appearance.labelFont}}>{f.name}</text></g>;
